with ins as (insert into public.artist_discography (artist_slug,artist_id,title,release_type,release_date,year,label,source_url) select x.s,a.id,x.ti,x.ty,x.d::date,x.y,x.l,x.u from json_to_recordset('[{"s":"audio-units","ti":"The Gateway Experience","ty":"ep","y":2023,"d":"2023-04-03","l":"ANAØH Records","u":"https://dirty-epic.com/2023/04/10/audio-units-the-gateway-experience-anaoh-records-april-3rd-2023/"},{"s":"djazz","ti":"7AM In Bangkok","ty":"ep","y":2026,"d":"2026-02-18","l":"All That DJazz","u":"https://ufo-network.com/?p=168240"},{"s":"dotdat","ti":"Steady Faith","ty":"album","y":2024,"d":"2024-12-06","l":null,"u":"https://dotdat.bandcamp.com/album/steady-faith"},{"s":"okedo","ti":"Impulse","ty":"single","y":2020,"d":null,"l":"Skip-A-Beat","u":"https://www.thewildcity.com/news/17589-okedo-amp-up-their-individual-voices-danceability-on-new-single-impulse"},{"s":"spryk","ti":"Emergence","ty":"ep","y":2014,"d":"2014-06-12","l":null,"u":"https://spryk.bandcamp.com/album/emergence"},{"s":"spryk","ti":"Parallax Barrier","ty":"single","y":2014,"d":"2014-09-14","l":null,"u":"https://spryk.bandcamp.com/track/parallax-barrier"}]'::json) as x(s text,ti text,ty text,y int,d text,l text,u text) join public.artists a on a.slug=x.s where not exists (select 1 from public.artist_discography d where d.artist_slug=x.s and lower(d.title)=lower(x.ti)) on conflict do nothing returning 1) select count(*) from ins;